import numpy as np
from itertools import combinations
import networkx as nx
L=open('init.xyz').read().split('\n')
n=int(L[0]); els=[];X=[]
for l in L[2:2+n]:
    p=l.split(); els.append(p[0]); X.append([float(x) for x in p[1:4]])
X=np.array(X)
cov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Co':1.3}
G=nx.Graph(); G.add_nodes_from(range(n))
for i,j in combinations(range(n),2):
    d=np.linalg.norm(X[i]-X[j])
    if d<(cov[els[i]]+cov[els[j]])*1.25: G.add_edge(i,j)

def rot(pts,axis_p,axis_d,ang):
    k=axis_d/np.linalg.norm(axis_d)
    v=pts-axis_p
    return axis_p + v*np.cos(ang)+np.cross(k,v)*np.sin(ang)+np.outer(v@k,k)*(1-np.cos(ang))

def group(a,b):
    """atoms on b-side when bond a-b cut"""
    H=G.copy(); H.remove_edge(a,b)
    return list(nx.node_connected_component(H,b))

def score(X,moving):
    s=1e9
    mv=set(moving)
    for i in moving:
        for j in range(n):
            if j in mv: continue
            if nx.shortest_path_length(G,i,j)<=3: continue
            d=np.linalg.norm(X[i]-X[j])
            s=min(s,d)
    return s

# rotatable bonds: P-CH(iPr), CH-CH3, Nam-CH2? keep. 
rotb=[]
for i,j in G.edges():
    if els[i]=='C' and els[j]=='C': 
        # methyl
        if sum(1 for k in G[j] if els[k]=='H')==3: rotb.append((i,j))
        if sum(1 for k in G[i] if els[k]=='H')==3: rotb.append((j,i))
