            Y=X.copy(); Y[mv]=rot(X[mv],X[a],X[b]-X[a],np.deg2rad(ang))
            s=score(Y,mv)
            if s>best[0]: best=(s,ang)
        if best[1]:
            X[mv]=rot(X[mv],X[a],X[b]-X[a],np.deg2rad(best[1]))
    print(it,'done')
with open('init2.xyz','w') as f:
    f.write(f"{n}\nfixed\n")
    for e,p in zip(els,X): f.write(f"{e} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
