import numpy as np, itertools, networkx as nx
from build3 import build, report, write

def rotm(pts,p0,d,ang):
    k=d/np.linalg.norm(d); v=pts-p0
    return p0+v*np.cos(ang)+np.cross(k,v)*np.sin(ang)+np.outer(v@k,k)*(1-np.cos(ang))

best=None
for tw in [30,40,50,60,100,110,120]:
    els,X,bonds=build(tw); n=len(els)
    G=nx.Graph(); G.add_nodes_from(range(n)); G.add_edges_from(bonds)
    spl=dict(nx.all_pairs_shortest_path_length(G,cutoff=3))
    # moves: (axis_a, axis_b, moving list) with C3 replication
    narm=(n-3)//3
    def grp(a,b):
        H=G.copy(); H.remove_edge(a,b); return sorted(nx.node_connected_component(H,b))
    moves=[]
    # within arm 0 (indices 3..3+narm-1)
    arm0=list(range(3,3+narm))
    for i,j in G.edges():
        if i>j: i,j=j,i
        if not(i in arm0 and j in arm0): continue
        ei,ej=els[i],els[j]
        if {ei,ej}=={'P','C'}:
            a,b=(i,j) if ei=='P' else (j,i)
            if els[b]=='C' and sum(1 for k in G[b] if els[k]=='H')==1:
                moves.append((a,b))
        if ei=='C' and ej=='C':
            if sum(1 for k in G[j] if els[k]=='H')==3: moves.append((i,j))
            elif sum(1 for k in G[i] if els[k]=='H')==3: moves.append((j,i))
    def repl(idx,k): 
        return idx if idx<3 else 3+((idx-3+k*narm-0)%(3*narm))
    def score(X,moving):
        mv=set(moving); s=9e9
        for i in moving:
            for j in range(n):
                if j in mv: continue
                if spl[i].get(j,9)<=3: continue
                d=np.linalg.norm(X[i]-X[j])
                if d<s: s=d
        return s
    # also whole-iPr swing about Co2-P axis
    Ps=[i for i in arm0 if els[i]=='P']
    swing=[]
    for p in Ps:
        g=[x for x in grp(2,p) if x!=p]
        # remove CH2 branch: keep only atoms whose path to p doesn't pass CH2(bonded to N)
        ch2=[k for k in G[p] if els[k]=='C' and any(els[m]=='N' for m in G[k])][0]
        g=[x for x in g if x not in grp(p,ch2)]
        swing.append((2,p,g))
    allmoves=[]
    for a,b in moves: allmoves.append(('b',a,b,grp(a,b)))
    for c,p,g in swing: allmoves.append(('s',c,p,g))
    for it in range(4):
        for typ,a,b,g in allmoves:
            # replicate to 3 arms
            cur=score(X, sum([[repl(x,k) for x in g] for k in range(3)],[]))
            bestang=0; bests=cur
            for ang in np.arange(10,360,10):
                Y=X.copy()
                for k in range(3):
                    ga=[repl(x,k) for x in g]; aa=repl(a,k); bb=repl(b,k)
                    Y[ga]=rotm(X[ga],X[aa],X[bb]-X[aa],np.deg2rad(ang))
                s=score(Y,sum([[repl(x,k) for x in g] for k in range(3)],[]))
                if s>bests: bests=s; bestang=ang
            if bestang:
                for k in range(3):
                    ga=[repl(x,k) for x in g]; aa=repl(a,k); bb=repl(b,k)
                    X[ga]=rotm(X[ga],X[aa],X[bb]-X[aa],np.deg2rad(bestang))
    b=report(els,X,bonds,False)
    worst=b[0][4] if b else 9
    print(tw,len(b),worst)
    if best is None or worst>best[0]:
        best=(worst,tw,els,X.copy(),bonds)
print("best",best[1],best[0])
els,X,bonds=best[2],best[3],best[4]
write('init3.xyz',els,X,'twist %s'%best[1])
report(els,X,bonds)
